import React, { useState } from "react";
import { Container } from "react-bootstrap";
import './MovieForm.css';
const MovieForm=(prop)=>{
   const [title,setTitle]= useState("");
    const [openingText,setOpeningText]=useState("");
   const[releaseDate,setReleaseDate]= useState("");

   const titleHandler=(event)=>{
    setTitle(event.target.value);
   }
   const openingTextHandler=(event)=>{
    setOpeningText(event.target.value);

   }
   const releaseDateHandler=(event)=>{
    setReleaseDate(event.target.value);
   }

   const submitHandler=(event)=>{
    event.preventDefault();

    const formData = {
        title: title,
        openingText: openingText,
        releaseDate: new Date(releaseDate),
      };

      setTitle('');
      setOpeningText('');
      setReleaseDate('');
  
   }

    return(
       <>
       <Container>
        <section>
       <form onSubmit={formHandler}>
        <label htmlFor="title">Title</label>
        <input type="text"
         value={title}
         onChange={titleHandler}
        
        ></input>
        <label htmlFor="openingText">OpeningText</label>
        <input type="text"
        value={openingText}
        onChange={openingTextHandler}
        ></input>
         
         <label htmlFor="releaseDate">ReleaseDate</label>
         <input
         type="date"
         value={releaseDate}
         onChange={releaseDateHandler}
         ></input>

          <button type="submit">Add Movie</button>
         
       </form>
      
       </section>
       </Container>
       </>
    )
}
export default MovieForm;
